// Cart amount in yen before rounding. `discount` is the customer's discount rate
// (0.1 = 10%), applied once. Carts with 10 or more lines then get an extra 5% bulk
// discount, also applied once.
export function exactTotal(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return subtotal * (1 - discount) * (1 - bulk);
}

// Cart total in yen. Fractions of a yen are dropped.
export function total(items, discount = 0) {
  return floorYen(exactTotal(items, discount));
}

// Drops the fraction of a yen. Float noise is cleared first, so an amount that is
// really a whole number (1000 * (1 - 0.9) = 99.99999999999997) does not lose a yen.
function floorYen(amount) {
  return Math.floor(Number(amount.toFixed(6)));
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

