  const few = [{ price: 100, qty: 2 }, { price: 50, qty: 1 }];
  const many = Array.from({ length: 10 }, () => ({ price: 1000, qty: 1 }));
  assert.equal(total(few, 0), 250);
  assert.equal(total(many, 0), 9500);
});

test('a discounted total drops the fraction of a yen', () => {
